    n = distance_matrix.shape[0]
    mean_distance = np.mean(distance_matrix)
    guide_matrix = np.zeros_like(distance_matrix)
    for i in range(n):
        connectivity = np.sum(distance_matrix[i] < mean_distance)
        for j in range(n):
            if i != j:
                penalty_factor = (1 + (connectivity / (n - 1) - 0.5))
                guide_matrix[i, j] = distance_matrix[i, j] * penalty_factor
    return guide_matrix

import numpy as np

def generate_guide_matrix(distance_matrix: np.ndarray) -> np.ndarray:
    n = distance_matrix.shape[0]
    guide_matrix = np.zeros_like(distance_matrix)
    mean_distance = np.mean(distance_matrix[distance_matrix > 0])
    for i in range(n):
        for j in range(n):
            if i != j and distance_matrix[i, j] > 0:
                connections = np.count_nonzero(distance_matrix[i])
                if connections > 1:
                    guide_matrix[i, j] = (distance_matrix[i, j] / connections) * (distance_matrix[i, j] / mean_distance)
                else:
                    guide_matrix[i, j] = distance_matrix[i, j]
    return guide_matrix

