def generate_guide_matrix(distance_matrix: np.ndarray) -> np.ndarray:
    n = distance_matrix.shape[0]
    mean_distance = np.mean(distance_matrix)
    harmonic_means = 2 / (1/distance_matrix + 1/mean_distance)
    guide_matrix = np.copy(distance_matrix)
    for i in range(n):
        for j in range(n):
            if i != j:
                if distance_matrix[i, j] < mean_distance:
                    guide_matrix[i, j] *= 0.75
                elif distance_matrix[i, j] > mean_distance:
                    guide_matrix[i, j] *= 1.25
                guide_matrix[i, j] += harmonic_means[i] / (j + 1)
    return guide_matrix

