def generate_guide_matrix(distance_matrix: np.ndarray) -> np.ndarray:
    n = distance_matrix.shape[0]
    guide_matrix = np.zeros((n, n))
    mean_distance = np.mean(distance_matrix[distance_matrix > 0])
    for i in range(n):
        connected_edges = distance_matrix[i] > 0
        density_factor = np.sum(connected_edges) / (n - 1)
        for j in range(n):
            if distance_matrix[i, j] > 0:
                distance_penalty = (distance_matrix[i, j] / mean_distance) * (1 + (1 - density_factor))
                guide_matrix[i, j] = distance_penalty
    return guide_matrix

