def generate_guide_matrix(distance_matrix: np.ndarray) -> np.ndarray:
    n = distance_matrix.shape[0]
    mean_distance = np.mean(distance_matrix)
    nearest_neighbor = np.min(distance_matrix + np.eye(n) * np.inf, axis=1)
    criticality = np.where(distance_matrix < nearest_neighbor[:, None], 0.5, 1.5)
    guide_matrix = distance_matrix.copy()
    for i in range(n):
        for j in range(n):
            if i != j:
                if distance_matrix[i, j] < mean_distance:
                    guide_matrix[i, j] *= 0.7
                elif distance_matrix[i, j] > nearest_neighbor[i]:
                    guide_matrix[i, j] *= 1.3
                guide_matrix[i, j] *= criticality[i, j]
    return guide_matrix

