def generate_guide_matrix(distance_matrix: np.ndarray) -> np.ndarray:
    n = distance_matrix.shape[0]
    avg_distance = np.mean(distance_matrix[distance_matrix != 0])
    guide_matrix = np.zeros_like(distance_matrix)
    for i in range(n):
        total_distance = np.sum(distance_matrix[i])
        for j in range(n):
            if i != j:
                edge_usage = (distance_matrix[i, j] / total_distance) if total_distance > 0 else 1
                proximity_penalty = np.clip((avg_distance - distance_matrix[i, j]) / avg_distance, 0.5, 1)
                guide_matrix[i, j] = edge_usage * proximity_penalty
    return guide_matrix
